-- Indonesia: ES/DE/FR milestone translations for the 6 milestones in
-- migration 357. Hand-translated, not machine copy-paste.

-- id-efaktur-mandatory-2014
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-efaktur-mandatory-2014', 'es', 'Se lanza el e-Faktur Pajak (factura electrónica de IVA) para contribuyentes designados', 'A partir del 1 de abril de 2014, la Dirección General de Impuestos de Indonesia (DJP) exigió a un primer grupo de contribuyentes registrados a efectos de IVA designados (Pengusaha Kena Pajak, PKP) que emitieran e-Faktur Pajak -- una factura electrónica de impuesto al valor agregado -- en lugar de facturas en papel. Este fue el origen del largo camino de Indonesia hacia la facturación electrónica obligatoria, aunque en esta etapa el requisito se aplicaba solo a un conjunto limitado de contribuyentes designados por la DJP, no a toda la población registrada a efectos de IVA.', '["No se requiere ninguna acción para este hito histórico -- se incluye como contexto de las entradas siguientes", "Si es un PKP anterior al despliegue de la facturación electrónica de Indonesia, tenga en cuenta que el requisito se amplió en etapas durante 2015 y 2016 -- vea los siguientes hitos"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-efaktur-mandatory-2014', 'de', 'e-Faktur Pajak (elektronische USt-Rechnung) wird für bestimmte Steuerpflichtige eingeführt', 'Ab dem 1. April 2014 verlangte Indonesiens Generaldirektion für Steuern (DJP) von einer ersten Gruppe designierter umsatzsteuerlich registrierter Steuerpflichtiger (Pengusaha Kena Pajak, PKP), e-Faktur Pajak -- eine elektronische Mehrwertsteuerrechnung -- statt Papierrechnungen auszustellen. Dies war der Ursprung von Indonesiens langjähriger Entwicklung hin zur verpflichtenden E-Rechnung, auch wenn die Pflicht zu diesem Zeitpunkt nur für eine begrenzte, von der DJP designierte Gruppe von Steuerpflichtigen galt, nicht für die gesamte umsatzsteuerlich registrierte Bevölkerung.', '["Für diesen historischen Meilenstein ist keine Handlung erforderlich -- er dient als Kontext für die folgenden Einträge", "Wenn Sie ein PKP sind, der älter ist als Indonesiens E-Rechnungs-Einführung, beachten Sie, dass sich die Pflicht 2015 und 2016 stufenweise erweiterte -- siehe die folgenden Meilensteine"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-efaktur-mandatory-2014', 'fr', 'Lancement de l''e-Faktur Pajak (facture électronique de TVA) pour les contribuables désignés', 'À compter du 1er avril 2014, la Direction générale des impôts d''Indonésie (DJP) a exigé d''un premier groupe de contribuables assujettis à la TVA désignés (Pengusaha Kena Pajak, PKP) qu''ils émettent des e-Faktur Pajak -- une facture électronique de taxe sur la valeur ajoutée -- plutôt que des factures papier. Ce fut l''origine de la longue transition de l''Indonésie vers la facturation électronique obligatoire, bien qu''à ce stade l''obligation ne s''appliquait qu''à un ensemble limité de contribuables désignés par la DJP, et non à l''ensemble des assujettis à la TVA.', '["Aucune action n''est requise pour ce jalon historique -- il est fourni à titre de contexte pour les entrées suivantes", "Si vous êtes un PKP antérieur au déploiement de la facturation électronique en Indonésie, notez que l''obligation s''est élargie par étapes en 2015 et 2016 -- voir les jalons suivants"]');

-- id-efaktur-java-bali-2015
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-efaktur-java-bali-2015', 'es', 'El e-Faktur se vuelve obligatorio para los contribuyentes de Java y Bali', 'A partir del 1 de julio de 2015, la DJP amplió el requisito de e-Faktur Pajak a todos los contribuyentes registrados a efectos de IVA (PKP) ubicados en Java y Bali -- las regiones más comercialmente densas de Indonesia -- mucho más allá del reducido conjunto de contribuyentes designados cubiertos desde 2014. Las empresas fuera de Java y Bali siguieron con la facturación en papel o manual durante un año más.', '["Los PKP con sede en Java o Bali deben confirmar que su proceso de facturación pasó por completo a e-Faktur desde esta fecha, si aún no lo ha hecho", "Las empresas que se expandan a Java o Bali deben presupuestar el cumplimiento de e-Faktur de inmediato, no según el calendario nacional posterior"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-efaktur-java-bali-2015', 'de', 'e-Faktur wird für Steuerpflichtige in Java und Bali verpflichtend', 'Ab dem 1. Juli 2015 weitete die DJP die e-Faktur-Pajak-Pflicht auf alle umsatzsteuerlich registrierten Steuerpflichtigen (PKP) in Java und Bali aus -- Indonesiens wirtschaftlich dichteste Regionen -- weit über die enge Gruppe der seit 2014 erfassten designierten Steuerpflichtigen hinaus. Unternehmen außerhalb von Java und Bali blieben noch ein weiteres Jahr bei Papier- oder manueller Rechnungsstellung.', '["PKP mit Sitz in Java oder Bali sollten prüfen, ob ihr Rechnungsprozess seit diesem Datum vollständig auf e-Faktur umgestellt wurde, falls noch nicht geschehen", "Unternehmen, die nach Java oder Bali expandieren, sollten die e-Faktur-Konformität sofort einplanen, nicht erst nach dem späteren landesweiten Zeitplan"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-efaktur-java-bali-2015', 'fr', 'L''e-Faktur devient obligatoire pour les contribuables de Java et Bali', 'À compter du 1er juillet 2015, la DJP a étendu l''obligation d''e-Faktur Pajak à tous les contribuables assujettis à la TVA (PKP) situés à Java et à Bali -- les régions les plus commercialement denses d''Indonésie -- bien au-delà du groupe restreint de contribuables désignés couvert depuis 2014. Les entreprises situées en dehors de Java et de Bali sont restées à la facturation papier ou manuelle pendant encore une année.', '["Les PKP basés à Java ou à Bali doivent vérifier que leur processus de facturation est bien passé entièrement à l''e-Faktur à compter de cette date, si ce n''est pas déjà fait", "Les entreprises qui s''implantent à Java ou à Bali doivent prévoir la conformité e-Faktur immédiatement, et non selon le calendrier national ultérieur"]');

-- id-efaktur-nationwide-2016
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-efaktur-nationwide-2016', 'es', 'El e-Faktur se vuelve obligatorio en todo el país para todos los contribuyentes registrados a efectos de IVA', 'A partir del 1 de julio de 2016, el e-Faktur Pajak se volvió obligatorio para todo contribuyente registrado a efectos de IVA (PKP) en Indonesia, completando el despliegue escalonado iniciado en 2014. Desde esta fecha, las facturas de IVA en papel dejaron de ser aceptables en cualquier parte del país -- todo PKP debía emitir facturas fiscales electrónicas, validadas después de su creación y con un Número de Serie de Factura Fiscal (Nomor Seri Faktur Pajak, NSFP) asignado. Este es el mandato de facturación electrónica fundacional y para toda la economía que la actual plataforma Coretax de Indonesia (desde 2025) ha sustituido desde entonces por un modelo de clearance en tiempo real.', '["Confirme que su sistema de facturación sigue emitiendo documentos e-Faktur válidos con un NSFP correctamente formateado", "Si su empresa se registró recientemente como PKP, confirme que su incorporación incluyó la configuración de e-Faktur en lugar de depender de la facturación en papel"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-efaktur-nationwide-2016', 'de', 'e-Faktur wird landesweit für alle umsatzsteuerlich registrierten Steuerpflichtigen verpflichtend', 'Ab dem 1. Juli 2016 wurde e-Faktur Pajak für jeden umsatzsteuerlich registrierten Steuerpflichtigen (PKP) in Indonesien verpflichtend und schloss damit den stufenweisen Rollout ab, der 2014 begann. Ab diesem Datum waren Papier-USt-Rechnungen im gesamten Land nicht mehr zulässig -- jeder PKP musste elektronische Steuerrechnungen ausstellen, die nach der Erstellung validiert und mit einer Steuerrechnungs-Seriennummer (Nomor Seri Faktur Pajak, NSFP) versehen wurden. Dies ist die grundlegende, gesamtwirtschaftliche E-Rechnungspflicht, die Indonesiens heutige Coretax-Plattform (seit 2025) inzwischen durch ein Echtzeit-Freigabemodell ersetzt hat.', '["Prüfen Sie, ob Ihr Rechnungssystem weiterhin gültige e-Faktur-Dokumente mit korrekt formatierter NSFP ausstellt", "Wenn sich Ihr Unternehmen erst kürzlich als PKP registriert hat, prüfen Sie, ob Ihr Onboarding die e-Faktur-Einrichtung umfasste, statt sich auf Papierrechnungen zu verlassen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-efaktur-nationwide-2016', 'fr', 'L''e-Faktur devient obligatoire dans tout le pays pour tous les contribuables assujettis à la TVA', 'À compter du 1er juillet 2016, l''e-Faktur Pajak est devenu obligatoire pour tout contribuable assujetti à la TVA (PKP) en Indonésie, achevant le déploiement progressif entamé en 2014. À partir de cette date, les factures de TVA papier n''étaient plus acceptées nulle part dans le pays -- chaque PKP devait émettre des factures fiscales électroniques, validées après création et dotées d''un numéro de série de facture fiscale (Nomor Seri Faktur Pajak, NSFP). Il s''agit de l''obligation de facturation électronique fondatrice, à l''échelle de toute l''économie, que la plateforme Coretax actuelle de l''Indonésie (depuis 2025) a depuis remplacée par un modèle de dédouanement en temps réel.', '["Vérifiez que votre système de facturation émet toujours des documents e-Faktur valides avec un NSFP correctement formaté", "Si votre entreprise s''est enregistrée récemment comme PKP, vérifiez que votre intégration incluait la configuration e-Faktur plutôt que de reposer sur la facturation papier"]');

-- id-coretax-launch-2025
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-coretax-launch-2025', 'es', 'Se lanza Coretax, iniciando el paso de la DJP de e-Faktur a una plataforma fiscal unificada', 'El 1 de enero de 2025, la Dirección General de Impuestos de Indonesia (DJP) lanzó Coretax, una nueva plataforma de administración destinada a sustituir eventualmente a e-Faktur y unificar la facturación, la declaración y el pago del IVA en un solo sistema. El despliegue inicial trajo problemas técnicos lo bastante importantes como para que la DJP reabriera la aplicación heredada e-Faktur Client Desktop como canal de respaldo mediante el decreto KEP-54/PJ/2025 (12 de febrero de 2025). Coretax genera automáticamente el número de serie NSFP de cada factura y acercó a Indonesia a un modelo de validación real en tiempo real, en lugar de las antiguas comprobaciones posteriores a la creación de e-Faktur.', '["Si todavía utiliza e-Faktur Client Desktop como respaldo, planifique su transición a Coretax mucho antes de la fecha de plena vigencia del 31 de diciembre de 2025", "Pruebe la integración de Coretax de su software de facturación/contabilidad (portal web, cliente de escritorio o Host-to-Host) antes de la plena vigencia, no durante ella"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-coretax-launch-2025', 'de', 'Coretax geht an den Start -- der Beginn von DJPs Übergang von e-Faktur zu einer einheitlichen Steuerplattform', 'Am 1. Januar 2025 führte Indonesiens Generaldirektion für Steuern (DJP) Coretax ein, eine neue Verwaltungsplattform, die e-Faktur langfristig ersetzen und USt-Rechnungsstellung, -Einreichung und -Zahlung in einem System vereinen soll. Der frühe Rollout brachte technische Probleme mit sich, die bedeutend genug waren, dass die DJP mit dem Erlass KEP-54/PJ/2025 (12. Februar 2025) die veraltete Anwendung e-Faktur Client Desktop als Ausweichkanal wieder öffnete. Coretax generiert die NSFP-Seriennummer jeder Rechnung automatisch und brachte Indonesien näher an ein echtes Echtzeit-Validierungsmodell, statt der älteren nachträglichen Prüfungen von e-Faktur.', '["Wenn Sie e-Faktur Client Desktop noch als Ausweichkanal nutzen, planen Sie Ihren Umstieg auf Coretax rechtzeitig vor dem vollständigen Inkrafttreten am 31. Dezember 2025 ein", "Testen Sie die Coretax-Integration Ihrer Rechnungs-/Buchhaltungssoftware (Webportal, Desktop-Client oder Host-to-Host) vor dem vollständigen Inkrafttreten, nicht erst währenddessen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-coretax-launch-2025', 'fr', 'Lancement de Coretax, amorçant la transition de la DJP de l''e-Faktur vers une plateforme fiscale unifiée', 'Le 1er janvier 2025, la Direction générale des impôts d''Indonésie (DJP) a lancé Coretax, une nouvelle plateforme d''administration destinée à remplacer à terme l''e-Faktur et à unifier la facturation, la déclaration et le paiement de la TVA en un seul système. Le déploiement initial a entraîné des problèmes techniques suffisamment importants pour que la DJP rouvre l''ancienne application e-Faktur Client Desktop comme canal de secours via le décret KEP-54/PJ/2025 (12 février 2025). Coretax génère automatiquement le numéro de série NSFP de chaque facture et a rapproché l''Indonésie d''un véritable modèle de validation en temps réel, plutôt que des anciens contrôles a posteriori d''e-Faktur.', '["Si vous utilisez encore e-Faktur Client Desktop comme canal de secours, planifiez votre transition vers Coretax bien avant la date d''entrée en vigueur intégrale du 31 décembre 2025", "Testez l''intégration Coretax de votre logiciel de facturation/comptabilité (portail web, client de bureau ou Host-to-Host) avant l''entrée en vigueur intégrale plutôt que pendant celle-ci"]');

-- id-per11-upload-deadline-2025
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-per11-upload-deadline-2025', 'es', 'PER-11/PJ/2025 traslada el plazo de carga de facturas al día 20 del mes siguiente', 'El reglamento de la DJP PER-11/PJ/2025, emitido el 22 de mayo de 2025, cambió el plazo para cargar las facturas fiscales en Coretax del día 15 al día 20 del mes siguiente a su emisión, y revisó las normas de series y códigos de transacción para las facturas procesadas a través de la plataforma. Un reglamento relacionado, PER-8/PJ/2025, se coordinó junto a él. Incumplir el plazo del día 20 hace que el comprador pierda la posibilidad de reclamar el crédito fiscal de IVA soportado en esa factura -- una consecuencia de cumplimiento real e inmediata, no una mera formalidad procedimental.', '["Actualice su calendario de facturación al nuevo plazo de carga en Coretax del día 20 del mes siguiente, en sustitución del anterior día 15", "Confirme que su equipo de cuentas por pagar entiende que una factura de proveedor cargada tarde puede hacer que su empresa pierda el crédito fiscal de IVA"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-per11-upload-deadline-2025', 'de', 'PER-11/PJ/2025 verschiebt die Rechnungs-Hochladefrist auf den 20. des Folgemonats', 'Die DJP-Verordnung PER-11/PJ/2025 vom 22. Mai 2025 änderte die Frist für das Hochladen von Steuerrechnungen auf Coretax vom 15. auf den 20. des auf die Ausstellung folgenden Monats und überarbeitete die Regeln für Serien- und Transaktionscodes für über die Plattform verarbeitete Rechnungen. Eine verwandte Verordnung, PER-8/PJ/2025, wurde parallel dazu koordiniert. Wird die Frist zum 20. des Monats verpasst, verliert der Käufer die Möglichkeit, den USt-Vorsteuerabzug für diese Rechnung geltend zu machen -- eine echte, unmittelbare Compliance-Folge, keine bloße verfahrenstechnische Formalität.', '["Aktualisieren Sie Ihren Rechnungskalender auf die neue Coretax-Hochladefrist zum 20. des Folgemonats statt des früheren 15.", "Stellen Sie sicher, dass Ihr Kreditorenbuchhaltungsteam versteht, dass eine verspätet hochgeladene Lieferantenrechnung Ihr Unternehmen den USt-Vorsteuerabzug kosten kann"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-per11-upload-deadline-2025', 'fr', 'PER-11/PJ/2025 déplace la date limite de téléversement des factures au 20 du mois suivant', 'Le règlement de la DJP PER-11/PJ/2025, publié le 22 mai 2025, a déplacé la date limite de téléversement des factures fiscales vers Coretax du 15 au 20 du mois suivant leur émission, et a révisé les règles de séries et de codes de transaction pour les factures traitées via la plateforme. Un règlement connexe, PER-8/PJ/2025, a été coordonné en parallèle. Le non-respect de l''échéance du 20 du mois entraîne pour l''acheteur la perte du droit de réclamer le crédit de TVA en amont sur cette facture -- une conséquence de conformité réelle et immédiate, non une simple formalité procédurale.', '["Mettez à jour votre calendrier de facturation avec la nouvelle échéance de téléversement Coretax du 20 du mois suivant, en remplacement du 15 précédent", "Vérifiez que votre équipe comptes fournisseurs comprend qu''une facture fournisseur téléversée en retard peut coûter à votre entreprise son crédit de TVA en amont"]');

-- id-coretax-full-enforcement-2025
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-coretax-full-enforcement-2025', 'es', 'Coretax pasa a estar plenamente vigente -- el visto bueno de la DJP se convierte en un requisito legal previo para la emisión de facturas', 'A partir del 31 de diciembre de 2025, Coretax pasó a estar plenamente vigente en todo el país para prácticamente todos los contribuyentes registrados a efectos de IVA (PKP), marcando un cambio real hacia un modelo de clearance: la aprobación de la DJP es ahora un requisito legal previo para que una factura fiscal sea válida, y no una comprobación posterior a su creación como en el antiguo sistema e-Faktur. Las facturas que carezcan del visto bueno de la DJP no pueden sustentar la deducción del IVA soportado del comprador. Los grandes contribuyentes pueden seguir utilizando e-Faktur Desktop o la integración Host-to-Host (H2H), pero esos canales ahora alimentan la validación en tiempo real de Coretax en lugar de operar de forma independiente. Algunas fuentes secundarias describen que Coretax se convierte en la interfaz principal para todas las operaciones de IVA a partir del 1 de enero de 2026, inmediatamente después de la plena vigencia -- trate ese matiz concreto como menos firmemente confirmado que la propia fecha de plena vigencia del 31 de diciembre de 2025.', '["Confirme que su flujo de facturación emite las facturas a través de un canal conectado a Coretax (portal web, cliente de escritorio o H2H) y no de ningún sistema heredado independiente", "Incorpore una comprobación de visto bueno de la DJP en tiempo real antes de considerar cualquier factura como definitiva -- una factura sin aprobar no es legalmente válida bajo el nuevo modelo"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-coretax-full-enforcement-2025', 'de', 'Coretax wird vollständig durchgesetzt -- die DJP-Freigabe wird zur rechtlichen Voraussetzung für die Rechnungsausstellung', 'Ab dem 31. Dezember 2025 wurde Coretax landesweit für nahezu alle umsatzsteuerlich registrierten Steuerpflichtigen (PKP) vollständig durchgesetzt und markiert damit einen echten Wechsel zu einem Freigabemodell: Die Genehmigung der DJP ist nun eine rechtliche Voraussetzung dafür, dass eine Steuerrechnung gültig ist, keine nachträgliche Prüfung wie unter dem alten e-Faktur-System. Rechnungen ohne DJP-Freigabe können den USt-Vorsteuerabzug des Käufers nicht stützen. Großsteuerpflichtige können weiterhin e-Faktur Desktop oder die Host-to-Host-Integration (H2H) nutzen, doch diese Kanäle fließen nun in Coretax'' Echtzeitvalidierung ein, statt unabhängig zu arbeiten. Einige Sekundärquellen beschreiben, dass Coretax ab dem 1. Januar 2026, unmittelbar nach der vollständigen Durchsetzung, zur primären Schnittstelle für alle USt-Vorgänge wird -- behandeln Sie diese konkrete Einordnung als weniger fest bestätigt als das Datum der vollständigen Durchsetzung selbst am 31. Dezember 2025.', '["Stellen Sie sicher, dass Ihr Rechnungsworkflow Rechnungen über einen mit Coretax verbundenen Kanal ausstellt (Webportal, Desktop-Client oder H2H) und nicht über ein eigenständiges Altsystem", "Bauen Sie eine Echtzeit-DJP-Freigabeprüfung ein, bevor Sie eine Rechnung als endgültig behandeln -- eine nicht freigegebene Rechnung ist unter dem neuen Modell rechtlich nicht gültig"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-coretax-full-enforcement-2025', 'fr', 'Coretax devient pleinement applicable -- le dédouanement de la DJP devient une condition légale préalable à l''émission des factures', 'À compter du 31 décembre 2025, Coretax est devenu pleinement applicable dans tout le pays pour la quasi-totalité des contribuables assujettis à la TVA (PKP), marquant un véritable basculement vers un modèle de dédouanement : l''approbation de la DJP est désormais une condition légale préalable à la validité d''une facture fiscale, et non un contrôle a posteriori comme sous l''ancien système e-Faktur. Les factures dépourvues de dédouanement de la DJP ne peuvent pas justifier la déduction de la TVA en amont de l''acheteur. Les grands contribuables peuvent continuer à utiliser e-Faktur Desktop ou l''intégration Host-to-Host (H2H), mais ces canaux alimentent désormais la validation en temps réel de Coretax plutôt que de fonctionner de manière indépendante. Certaines sources secondaires décrivent Coretax comme devenant l''interface principale pour toutes les opérations de TVA à compter du 1er janvier 2026, immédiatement après l''entrée en vigueur intégrale -- ce point précis doit être considéré comme moins fermement confirmé que la date d''entrée en vigueur intégrale du 31 décembre 2025 elle-même.', '["Vérifiez que votre flux de facturation émet les factures via un canal connecté à Coretax (portail web, client de bureau ou H2H) plutôt que via un système hérité autonome", "Intégrez un contrôle de dédouanement DJP en temps réel avant de considérer une facture comme définitive -- une facture non dédouanée n''est pas juridiquement valable sous le nouveau modèle"]');
